/**
 * MorphoNews Layout: 速度論的プリズム・シャード・エントロピー
 * Generated: 2026-02-12_0959
 * Generation: #76
 * Mood: Agentic
 * Evolution: scroll-driven animationsを用いたclip-pathの動的変形 + インターセクションによる色の彩度復元 + 疑似要素による磁気フィールド・エフェクト
 * Description: 第76世代の進化。前回の『足場（Scaffold）』による静的な構築概念を破壊し、情報が断片（Shard）から秩序へと再構成される『動的エントロピーの制御』を表現。CSS clip-pathとscroll-driven animationsを組み合わせ、ユーザーのスクロール量に応じて幾何学的な破片が完全な矩形へと収束・整列するキネティックな体験を構築。個々のカードは不規則な多角形から始まり、視覚的なノイズが情報の核心へと変換されるプロセスをシミュレートしています。
 */
/**
 * MorphoNews Layout: agentic-kinetic-shard-v76
 * Generation: #76 (Agentic)
 */

@property --shard-progress {
    syntax: '<number>';
    initial-value: 0;
    inherits: true;
}

:root {
    --layout-max-width: 1400px;
    --layout-news-columns: repeat(6, 1fr);
    --layout-card-gap: 2rem;
    --layout-card-direction: column;
    --layout-animation-style: shard-convergence;
    --shard-skew: 15deg;
}

#news-container {
    max-width: var(--layout-max-width);
    margin: 10rem auto;
    padding: 4rem 2rem;
    display: grid;
    grid-template-columns: var(--layout-news-columns);
    gap: var(--layout-card-gap);
    perspective: 2000px;
}

.news-card {
    position: relative;
    grid-column: span 3;
    background: var(--morph-bg-secondary);
    border: 1px solid rgba(var(--morph-accent-primary-rgb), 0.2);
    padding: 2rem;
    display: flex;
    flex-direction: var(--layout-card-direction);
    min-height: 400px;
    transition: all 0.6s cubic-bezier(0.23, 1, 0.32, 1);

    /* Scroll-driven Animation Trigger */
    view-timeline: --card-scroll block;
    animation: converge-shards both linear;
    animation-timeline: --card-scroll;
    animation-range: entry 0% cover 50%;

    /* Default clip-path: Distorted Shard */
    clip-path: polygon(10% 0%, 100% 0%, 90% 100%, 0% 100%);
    filter: grayscale(1) brightness(0.7);
}

.news-card:nth-child(even) {
    grid-column: span 3;
    margin-top: 4rem;
    clip-path: polygon(0% 0%, 90% 0%, 100% 100%, 10% 100%);
}

.news-card:nth-child(3n) {
    grid-column: span 6;
    aspect-ratio: 21/9;
    clip-path: polygon(5% 15%, 95% 0%, 100% 85%, 0% 100%);
}

@keyframes converge-shards {
    0% {
        transform: translateY(100px) rotateY(20deg) scale(0.9);
        filter: grayscale(1) brightness(0.5) blur(5px);
        clip-path: polygon(30% 0%, 70% 0%, 100% 100%, 0% 100%);
    }
    100% {
        transform: translateY(0) rotateY(0) scale(1);
        filter: grayscale(0) brightness(1) blur(0px);
        clip-path: polygon(0% 0%, 100% 0%, 100% 100%, 0% 100%);
    }
}

.news-card:hover {
    border-color: var(--morph-accent-primary);
    box-shadow: 0 0 30px rgba(var(--morph-accent-primary-rgb), 0.2);
    transform: translateZ(50px);
    z-index: 10;
}

.news-card::after {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(135deg, transparent 0%, rgba(var(--morph-accent-primary-rgb), 0.05) 50%, transparent 100%);
    transform: translateX(-100%);
    transition: transform 0.8s ease;
}

.news-card:hover::aft
```


